{
  "ok": true,
  "count": 4,
  "scenarios": [
    {
      "scenario": "damped_decay",
      "title": "阻尼振子 · 测包络衰减常数",
      "story": "一台带阻尼的弹簧振子实验台（欠阻尼，会振荡着衰减）。可设定质量 m、劲度 k 与阻尼系数 c，仪器由整段轨迹的**峰值包络**给出衰减常数 gamma。",
      "parameters": [
        {
          "name": "m",
          "default": 1.0,
          "sampling_range": [
            0.2,
            2.0
          ],
          "note": "可由你设定"
        },
        {
          "name": "k",
          "default": 8.0,
          "sampling_range": [
            2.0,
            20.0
          ],
          "note": "可由你设定"
        },
        {
          "name": "c",
          "default": 0.05,
          "sampling_range": [
            0.01,
            0.15
          ],
          "note": "可由你设定"
        },
        {
          "name": "A",
          "default": 0.1,
          "sampling_range": [
            0.01,
            0.5
          ],
          "note": "可由你设定"
        }
      ],
      "measured": {
        "name": "gamma",
        "meaning": "包络衰减常数",
        "unit": null
      },
      "note": "仿真台会记录整段过程并按物理方法给出读数；参数可以任意设定。各参数与读数的**量纲都不提供**，请根据名称与物理语境推断。"
    },
    {
      "scenario": "kepler_speed",
      "title": "圆轨道天体 · 测比动能",
      "story": "一个二体系统仿真台：中心天体质量为 M（这里按**小天体/小行星**的量级取，让读数的量级便于处理），卫星在半径 a 的**圆轨道**上运动，引力常数 G 在本仿真里是可调的（用于检验你对万有引力量纲的理解）。仪器给出卫星的**比动能**（单位质量的动能）。",
      "parameters": [
        {
          "name": "M",
          "default": 6e+22,
          "sampling_range": [
            5e+21,
            5e+23
          ],
          "note": "可由你设定"
        },
        {
          "name": "a",
          "default": 7000000.0,
          "sampling_range": [
            1000000.0,
            100000000.0
          ],
          "note": "可由你设定"
        },
        {
          "name": "G",
          "default": 6.674e-11,
          "sampling_range": [
            3e-11,
            1.5e-10
          ],
          "note": "可由你设定"
        }
      ],
      "measured": {
        "name": "eps",
        "meaning": "卫星比动能（单位质量的动能）",
        "unit": null
      },
      "note": "仿真台会记录整段过程并按物理方法给出读数；参数可以任意设定。各参数与读数的**量纲都不提供**，请根据名称与物理语境推断。"
    },
    {
      "scenario": "rc_discharge",
      "title": "RC 放电 · 测时间常数",
      "story": "一个电容通过电阻放电的实验台。可设定电阻 R、电容 C 与初始电压 V0，仪器由放电曲线给出时间常数 tau。初始电压是不是影响 tau，需要你自己判断。",
      "parameters": [
        {
          "name": "R",
          "default": 1000.0,
          "sampling_range": [
            100.0,
            10000.0
          ],
          "note": "可由你设定"
        },
        {
          "name": "C",
          "default": 0.0001,
          "sampling_range": [
            1e-06,
            0.001
          ],
          "note": "可由你设定"
        },
        {
          "name": "V0",
          "default": 5.0,
          "sampling_range": [
            1.0,
            12.0
          ],
          "note": "可由你设定"
        }
      ],
      "measured": {
        "name": "tau",
        "meaning": "时间常数",
        "unit": null
      },
      "note": "仿真台会记录整段过程并按物理方法给出读数；参数可以任意设定。各参数与读数的**量纲都不提供**，请根据名称与物理语境推断。"
    },
    {
      "scenario": "spring_period",
      "title": "弹簧振子 · 测振动周期",
      "story": "一台理想弹簧振子实验台。你可以设定质量参数 m、弹簧劲度 k 与初始振幅 A，仪器记录整段振动过程，并给出测得的周期 T。振幅 A 是你自己设定的，它是不是真的影响读数，需要你自己判断。",
      "parameters": [
        {
          "name": "m",
          "default": 1.0,
          "sampling_range": [
            0.2,
            2.0
          ],
          "note": "可由你设定"
        },
        {
          "name": "k",
          "default": 8.0,
          "sampling_range": [
            2.0,
            20.0
          ],
          "note": "可由你设定"
        },
        {
          "name": "A",
          "default": 0.1,
          "sampling_range": [
            0.01,
            0.5
          ],
          "note": "可由你设定"
        }
      ],
      "measured": {
        "name": "T",
        "meaning": "振动周期",
        "unit": null
      },
      "note": "仿真台会记录整段过程并按物理方法给出读数；参数可以任意设定。各参数与读数的**量纲都不提供**，请根据名称与物理语境推断。"
    }
  ],
  "note": "这些是**可驱动的数值仿真实验台**（RK4 数值积分）。用 run_simulation 跑一次看读数与时间序列，或直接用 run_sweep 跑一批实验生成数据集。"
}
